const { chromium }=require('playwright');const base='http://127.0.0.1:8787';async function api(r,m,p,d){const s=await r.fetch(base+p,{method:m,headers:d===undefined?undefined:{'Content-Type':'application/json'},data:d});const j=await s.json();if(s.status()<200||s.status()>299)throw new Error(j.message||`${s.status()}`);return j}(async()=>{const b=await chromium.launch({headless:true}),c=await b.newContext({viewport:{width:1440,height:900}});try{const pw='Diagnostic-Editor-2026!',s=await c.request.post(base+'/api/auth/signup',{data:{username:'diagnostic_editor',displayName:'Diagnostic Editor',email:'diagnostic@example.test',password:pw,rememberMe:false}});if(s.status()!==201)throw new Error('signup');const o=await api(c.request,'GET','/api/onboarding'),r=o.relationshipOptions||o.relationships||o.options?.relationships||[],i=o.intentionOptions||o.intentions||o.options?.intentions||[];await api(c.request,'POST','/api/onboarding/relationship',{relationshipId:r[0].id});await api(c.request,'POST','/api/onboarding/intentions',{intentionIds:i.slice(0,2).map(x=>x.id)});await api(c.request,'POST','/api/bootstrap/owner',{password:pw});const p=await c.newPage();const errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto(base+'/dashboard',{waitUntil:'networkidle'});console.log('BEFORE='+JSON.stringify(await p.evaluate(()=>({editing:dashboardState.editing,payload:Boolean(dashboardState.payload),toolbarHidden:document.querySelector('#dashboard-editor-toolbar').hidden,buttonHidden:document.querySelector('#customize-dashboard').hidden,openSource:String(openEditor).slice(0,500)}))));await p.locator('#customize-dashboard').click();await p.waitForTimeout(1000);console.log('AFTER='+JSON.stringify(await p.evaluate(()=>({editing:dashboardState.editing,payload:Boolean(dashboardState.payload),toolbarHidden:document.querySelector('#dashboard-editor-toolbar').hidden,buttonHidden:document.querySelector('#customize-dashboard').hidden,advanced:Boolean(document.querySelector('#dashboard-advanced-tools')),activePage:document.querySelector('.dashboard-page-tab.active')?.dataset.pageId,errors:window.__dashboardEditorErrors||[]}))));console.log('PAGE_ERRORS='+JSON.stringify(errors));}finally{await c.close();await b.close()}})().catch(e=>{console.error(e.stack||e);process.exit(1)});
